/**
 * Add some rootXML info to this mime-type
 *
 * @param namespaceURI
 * @param localName
 */
void addRootXML(String namespaceURI, String localName) {
    if (rootXML == null) {
        rootXML = new ArrayList<>();
    }
    rootXML.add(new RootXML(this, namespaceURI, localName));
}
